```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string wordToCount; // das Wort, das gezählt werden soll
    int count = 0; // die Anzahl der Vorkommen des Wortes

    // Anweisung zum Eingabe des Wortes
    cout << "Bitte geben Sie das Wort ein, das gezählt werden soll: ";
    cin >> wordToCount;

    // Konvertieren des Wortes in Kleinbuchstaben
    transform(wordToCount.begin(), wordToCount.end(), wordToCount.begin(), ::tolower);

    // Öffnen der Textdatei
    ifstream inputFile("dateiname.txt");

    if (!inputFile.is_open()) {
        cout << "Fehler: Datei konnte nicht geöffnet werden." << endl;
        return 1;
    }

    // Lesen der Datei Zeile für Zeile
    string line;
    while (getline(inputFile, line)) {

        // Konvertieren der Zeile in Kleinbuchstaben
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Suchen nach dem Wort in der Zeile
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != string::npos) {
            count++;
            pos += wordToCount.length();
        }
    }

    // Schließen der Datei
    inputFile.close();

    // Ausgabe des Ergebnisses
