int fibonacci(int n) {
    int fib[n+2]; // Array, das die Fibonacci-Zahlen speichert
    fib[0] = 0; // Erste Fibonacci-Zahl
    fib[1] = 1; // Zweite Fibonacci-Zahl

    // Berechnen der Fibonacci-Zahlen für n
    for (int I = 2; I <= n; i++) {
